import{_ as t,o as a,c as n,ao as r}from"./chunks/framework.DAOq3-pm.js";const g=JSON.parse('{"title":"Learning track","description":"","frontmatter":{},"headers":[],"relativePath":"course.md","filePath":"course.md","lastUpdated":null}'),i={name:"course.md"};function s(l,e,o,h,d,p){return a(),n("div",null,[...e[0]||(e[0]=[r(`<h1 id="Learning-track" tabindex="-1">Learning track <a class="header-anchor" href="#Learning-track" aria-label="Permalink to &quot;Learning track {#Learning-track}&quot;">​</a></h1><p>The repository includes a pen-and-paper course, in <code>LearningTrack/</code>, that leads from elementary quantum mechanics to the complete Godfrey–Isgur algorithm. It is written for physics students who want to understand the model well enough to implement it.</p><h2 id="Contents" tabindex="-1">Contents <a class="header-anchor" href="#Contents" aria-label="Permalink to &quot;Contents {#Contents}&quot;">​</a></h2><p><strong>Part 1: theory sheets</strong></p><ol><li><p><a href="https://github.com/mmikhasenko/GIModel.jl/releases/download/learning-sheets/01_radial_quantum_mechanics.pdf" target="_blank" rel="noreferrer">Radial quantum mechanics</a></p></li><li><p><a href="https://github.com/mmikhasenko/GIModel.jl/releases/download/learning-sheets/02_angular_momentum_and_mesons.pdf" target="_blank" rel="noreferrer">Angular momentum and mesons</a></p></li><li><p><a href="https://github.com/mmikhasenko/GIModel.jl/releases/download/learning-sheets/03_variational_and_semirelativistic.pdf" target="_blank" rel="noreferrer">Variational methods and the semirelativistic kinetic energy</a></p></li><li><p><a href="https://github.com/mmikhasenko/GIModel.jl/releases/download/learning-sheets/04_color_confinement_running_coupling.pdf" target="_blank" rel="noreferrer">Color, confinement and the running coupling</a></p></li><li><p><a href="https://github.com/mmikhasenko/GIModel.jl/releases/download/learning-sheets/05_relativization_and_smearing.pdf" target="_blank" rel="noreferrer">Relativization and smearing</a></p></li><li><p><a href="https://github.com/mmikhasenko/GIModel.jl/releases/download/learning-sheets/06_spin_fine_structure.pdf" target="_blank" rel="noreferrer">Spin-dependent fine structure</a></p></li><li><p><a href="https://github.com/mmikhasenko/GIModel.jl/releases/download/learning-sheets/07_state_and_flavor_mixing.pdf" target="_blank" rel="noreferrer">State and flavor mixing</a></p></li><li><p><a href="https://github.com/mmikhasenko/GIModel.jl/releases/download/learning-sheets/08_decay_observables.pdf" target="_blank" rel="noreferrer">Decay observables</a></p></li><li><p><a href="https://github.com/mmikhasenko/GIModel.jl/releases/download/learning-sheets/09_full_algorithm_capstone.pdf" target="_blank" rel="noreferrer">The full algorithm: a capstone</a></p></li></ol><p><strong>Part 2: computational track</strong></p><ul><li>C1: <a href="https://github.com/mmikhasenko/GIModel.jl/releases/download/learning-sheets/C1_computational_discovery.pdf" target="_blank" rel="noreferrer">computational discovery</a></li></ul><p>Each sheet contains problems, worked solutions and short concept checks after the solutions. Problem statements give all inputs, conventions and the requested result, so a student can start without reading the solution.</p><p>The links download the PDFs from the latest successful build on <code>main</code>, which the Learning sheets workflow publishes to a dedicated <a href="https://github.com/mmikhasenko/GIModel.jl/releases/tag/learning-sheets" target="_blank" rel="noreferrer">release</a>.</p><h2 id="Building-the-PDFs" tabindex="-1">Building the PDFs <a class="header-anchor" href="#Building-the-PDFs" aria-label="Permalink to &quot;Building the PDFs {#Building-the-PDFs}&quot;">​</a></h2><p>To build them yourself, a LaTeX installation with <code>latexmk</code> is required:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> LearningTrack</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span></span></code></pre></div><p>The PDFs are written to <code>LearningTrack/pdf/</code>.</p><h2 id="Using-it-with-the-package" tabindex="-1">Using it with the package <a class="header-anchor" href="#Using-it-with-the-package" aria-label="Permalink to &quot;Using it with the package {#Using-it-with-the-package}&quot;">​</a></h2><p>Each sheet corresponds to a part of this documentation:</p><table tabindex="0"><thead><tr><th style="text-align:right;">sheet</th><th style="text-align:right;">documentation</th></tr></thead><tbody><tr><td style="text-align:right;">1–3</td><td style="text-align:right;"><a href="/GIModel.jl/previews/PR11/manual/physics#The-model">The model</a>, <a href="/GIModel.jl/previews/PR11/manual/solvers#Solvers-and-convergence">Solvers and convergence</a></td></tr><tr><td style="text-align:right;">4–6</td><td style="text-align:right;"><a href="/GIModel.jl/previews/PR11/manual/physics#The-model">The model</a>, <a href="/GIModel.jl/previews/PR11/manual/spectra#Computing-a-spectrum">Computing a spectrum</a></td></tr><tr><td style="text-align:right;">7</td><td style="text-align:right;"><a href="/GIModel.jl/previews/PR11/manual/spectra#Computing-a-spectrum">Computing a spectrum</a>, <a href="/GIModel.jl/previews/PR11/manual/isoscalar#Isoscalar-flavor-mixing">Isoscalar flavor mixing</a></td></tr><tr><td style="text-align:right;">8</td><td style="text-align:right;"><a href="/GIModel.jl/previews/PR11/manual/transitions#Transitions-and-decays">Transitions and decays</a></td></tr><tr><td style="text-align:right;">9</td><td style="text-align:right;"><a href="/GIModel.jl/previews/PR11/tutorials/charmonium#Charmonium,-start-to-finish">Charmonium, start to finish</a></td></tr></tbody></table>`,16)])])}const m=t(i,[["render",s]]);export{g as __pageData,m as default};
